/**
 * The whole thread for one issue, in reading order: top-level comments oldest
 * first, each followed by its replies. A deleted top-level comment takes its
 * thread with it — nothing to anchor the replies to once the opener is gone.
 */
export async function listThread(
  orgId: OrgId,
  issueId: IssueId,
): Promise<readonly CommentThreadNode[]> {
  const rows = getDb()
    .select({ comment: comments, author: users })
    .from(comments)
    .innerJoin(users, eq(users.id, comments.authorId))
    .where(
      and(
        orgPredicate(comments.orgId, orgId),
        eq(comments.issueId, issueId),
      ),
    )
    .orderBy(asc(comments.createdAt))
    .all();

  const decorated: CommentWithAuthor[] = rows.map((row) => ({
    ...toComment(row.comment),
    author: toUser(row.author),
  }));

  const repliesBy = new Map<string, CommentWithAuthor[]>();
  for (const comment of decorated) {
    if (comment.parentId === null) continue;
    const bucket = repliesBy.get(comment.parentId) ?? [];
    bucket.push(comment);
    repliesBy.set(comment.parentId, bucket);
  }

  return decorated
    .filter((comment) => comment.parentId === null && comment.archivedAt === null)
    .map((comment) => ({
      comment,
      replies: repliesBy.get(comment.id) ?? [],
    }));
}

input.new_string:
/**
 * The whole thread for one issue, in reading order: top-level comments oldest
 * first, each followed by every reply that descends from it — direct or
 * through other replies — in posting order. A deleted comment stays where it
 * was as a placeholder without its text, so the replies beneath it stay put.
 */
export async function listThread(
  orgId: OrgId,
  issueId: IssueId,
): Promise<readonly CommentThreadNode[]> {
  const rows = getDb()
    .select({ comment: comments, author: users })
    .from(comments)
    .innerJoin(users, eq(users.id, comments.authorId))
    .where(
      and(
        orgPredicate(comments.orgId, orgId),
        eq(comments.issueId, issueId),
      ),
    )
    .orderBy(asc(comments.createdAt), asc(comments.id))
    .all();

  const decorated: CommentWithAuthor[] = rows.map((row) => ({
    ...toComment(row.comment),
    author: toUser(row.author),
  }));

  // Posting order across the whole issue; branches are sorted back into it.
  const position = new Map(decorated.map((comment, index) => [comment.id, index]));

  const childrenOf = new Map<string, CommentWithAuthor[]>();
  for (const comment of decorated) {
    if (comment.parentId === null) continue;
    const siblings = childrenOf.get(comment.parentId) ?? [];
    siblings.push(comment);
    childrenOf.set(comment.parentId, siblings);
  }

  const descendantsOf = (root: CommentWithAuthor): CommentWithAuthor[] => {
    const found: CommentWithAuthor[] = [];
    const pending = [...(childrenOf.get(root.id) ?? [])];
    for (let next = pending.pop(); next !== undefined; next = pending.pop()) {
      found.push(next);
      pending.push(...(childrenOf.get(next.id) ?? []));
    }
    return found.sort(
      (a, b) => (position.get(a.id) ?? 0) - (position.get(b.id) ?? 0),
    );
  };

  return decorated
    .filter((comment) => comment.parentId === null)
    .map((comment) => ({
      comment: asThreadEntry(comment),
      replies: descendantsOf(comment).map(asThreadEntry),
    }));
}

/** A deleted comment keeps its identity and place, but not its text. */
function asThreadEntry(comment: CommentWithAuthor): CommentWithAuthor {
  if (comment.archivedAt === null) return comment;
  return { ...comment, body: "", mentionedUserIds: [] };
}

