import { afterAll, afterEach, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("./server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("./server/_support/doubles/misc")).loggerModule);

import { consumeRateLimit } from "@/lib/rate-limit";
import * as commentRepo from "@/server/repositories/comment-repository";
import * as memberRepo from "@/server/repositories/member-repository";
import * as userRepo from "@/server/repositories/user-repository";
import * as commentService from "@/server/services/comment-service";
import * as issueService from "@/server/services/issue-service";
import * as notificationService from "@/server/services/notification-service";
import * as searchService from "@/server/services/search-service";
import { registerSearchListeners } from "@/server/services/search-service";
import { createTenant, issueInput, useTemporaryDatabase } from "./server/_support/fixtures";
import type { Tenant } from "./server/_support/fixtures";
import type { Issue } from "@/types/issue";
import type { UserId } from "@/types/common";

let cleanup: () => void;
let t: Tenant;
let other: Tenant;
let longtimeId: UserId;
let xId: UserId;
let elsewhereViewerId: UserId;
let issue: Issue;

async function alertCount(recipient: UserId, kind: string, issueId: string) {
  const page = await notificationService.listNotifications(t.actors.owner, {
    orgId: t.org.id,
    recipientId: recipient,
    unreadOnly: false,
    kind: [kind as never],
    limit: 100,
    cursor: null,
  });
  return page.items.filter((n) => n.href === `/issues/${issueId}`).length;
}

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  t = await createTenant("scratchfix", "growth");
  other = await createTenant("scratchother", "growth");
  registerSearchListeners();

  const longtime = await userRepo.insertUser({
    email: "longtime@scratchfix.test",
    name: "Long Time",
    passwordHash: "seed",
  });
  await memberRepo.insertMember(t.org.id, longtime.id, "member", null);
  longtimeId = longtime.id;

  for (let i = 0; i < 110; i += 1) {
    const filler = await userRepo.insertUser({
      email: `filler${i}@scratchfix.test`,
      name: `Filler ${i}`,
      passwordHash: "seed",
    });
    await memberRepo.insertMember(t.org.id, filler.id, "member", null);
  }

  const x = await userRepo.insertUser({
    email: "x@scratchfix.test",
    name: "Single",
    passwordHash: "seed",
  });
  await memberRepo.insertMember(t.org.id, x.id, "member", null);
  xId = x.id;

  const elsewhere = await userRepo.insertUser({
    email: "Viewer@elsewhere.test",
    name: "Elsewhere viewer",
    passwordHash: "seed",
  });
  await memberRepo.insertMember(t.org.id, elsewhere.id, "member", null);
  elsewhereViewerId = elsewhere.id;

  issue = await issueService.createIssue(
    t.actors.owner,
    issueInput(t.org.id, t.project.id, { title: "Mention matrix" }),
  );
});

afterAll(() => {
  cleanup();
});

afterEach(() => {
  vi.useRealTimers();
});

describe("scratch verification", () => {
  it("mentions long-standing, read-only, shared-handle and single-letter members; ignores author, code, other orgs", async () => {
    const comment = await commentService.createComment(t.actors.member, {
      orgId: t.org.id,
      issueId: issue.id,
      body: "ping @longtime, @viewer, @x and @owner and @member `@admin`",
      parentId: null,
      mentionedUserIds: [],
    });

    expect(comment.mentionedUserIds).toHaveLength(5);
    expect(comment.mentionedUserIds).toEqual(
      expect.arrayContaining([
        longtimeId,
        t.userIds.viewer,
        elsewhereViewerId,
        xId,
        t.userIds.owner,
      ]),
    );
    expect(comment.mentionedUserIds).not.toContain(t.userIds.member);
    expect(comment.mentionedUserIds).not.toContain(t.userIds.admin);
    expect(comment.mentionedUserIds).not.toContain(other.userIds.owner);

    expect(await alertCount(longtimeId, "comment_mention", issue.id)).toBe(1);
    expect(await alertCount(t.userIds.viewer, "comment_mention", issue.id)).toBe(1);
    expect(await alertCount(elsewhereViewerId, "comment_mention", issue.id)).toBe(1);
    expect(await alertCount(xId, "comment_mention", issue.id)).toBe(1);
    expect(await alertCount(t.userIds.member, "comment_mention", issue.id)).toBe(0);
  });

  it("gives each member their own posting bucket", async () => {
    let denied = false;
    for (let i = 0; i < 5000 && !denied; i += 1) {
      denied = !(await consumeRateLimit(t.org.id, "comment:create", 1, "burst-member")).allowed;
    }
    expect(denied).toBe(true);
    expect(
      (await consumeRateLimit(t.org.id, "comment:create", 1, "quiet-member")).allowed,
    ).toBe(true);
  });

  it("keeps the full thread, placeholders for deleted comments, and the live count", async () => {
    const issue2 = await issueService.createIssue(
      t.actors.owner,
      issueInput(t.org.id, t.project.id, { title: "Thread shape" }),
    );
    const top = await commentService.createComment(t.actors.owner, {
      orgId: t.org.id, issueId: issue2.id, body: "top", parentId: null, mentionedUserIds: [],
    });
    const r1 = await commentService.createComment(t.actors.member, {
      orgId: t.org.id, issueId: issue2.id, body: "first reply", parentId: top.id, mentionedUserIds: [],
