        orgId: t.org.id, commentId: c.id, body: "window edit two",
      }),
    ).rejects.toThrow(/edit window/);

    // A moderator is not bound by the window.
    await expect(
      commentService.updateComment(t.actors.admin, {
        orgId: t.org.id, commentId: c.id, body: "moderated",
      }),
    ).resolves.toMatchObject({ body: "moderated" });
  });

  it("re-reads mentions on edit, alerts only new ones, and indexes the new text", async () => {
    vi.useRealTimers();
    const issue3 = await issueService.createIssue(
      t.actors.owner,
      issueInput(t.org.id, t.project.id, { title: "Edit mentions" }),
    );
    const c = await commentService.createComment(t.actors.member, {
      orgId: t.org.id, issueId: issue3.id, body: "first @admin", parentId: null, mentionedUserIds: [],
    });
    expect(c.mentionedUserIds).toEqual([t.userIds.admin]);
    expect(await alertCount(t.userIds.admin, "comment_mention", issue3.id)).toBe(1);

    const edited = await commentService.updateComment(t.actors.member, {
      orgId: t.org.id, commentId: c.id, body: "zebraword @admin and @viewer",
    });
    expect(edited.mentionedUserIds).toEqual(
      expect.arrayContaining([t.userIds.admin, t.userIds.viewer]),
    );
    expect(edited.mentionedUserIds).toHaveLength(2);
    expect(await alertCount(t.userIds.admin, "comment_mention", issue3.id)).toBe(1);
    expect(await alertCount(t.userIds.viewer, "comment_mention", issue3.id)).toBe(1);

    const hits = await searchService.search(t.actors.owner, {
      orgId: t.org.id, q: "zebraword", kinds: ["comment"], limit: 25, cursor: null,
    });
    expect(hits.items.map((h) => h.id)).toContain(c.id);
  });

  it("alerts once per comment: mention beats comment alert; replies alert the parent author", async () => {
    const issue4 = await issueService.createIssue(
      t.actors.owner,
      issueInput(t.org.id, t.project.id, { title: "Precedence", assigneeId: t.userIds.admin }),
    );
    const c = await commentService.createComment(t.actors.member, {
      orgId: t.org.id, issueId: issue4.id, body: "hey @admin look", parentId: null, mentionedUserIds: [],
    });

    expect(await alertCount(t.userIds.admin, "comment_mention", issue4.id)).toBe(1);
    expect(await alertCount(t.userIds.admin, "comment_created", issue4.id)).toBe(0);
    expect(await alertCount(t.userIds.owner, "comment_created", issue4.id)).toBe(1);
    expect(await alertCount(t.userIds.member, "comment_created", issue4.id)).toBe(0);

    await commentService.createComment(t.actors.admin, {
      orgId: t.org.id, issueId: issue4.id, body: "a reply", parentId: c.id, mentionedUserIds: [],
    });

    expect(await alertCount(t.userIds.member, "comment_created", issue4.id)).toBe(1);
    expect(await alertCount(t.userIds.admin, "comment_created", issue4.id)).toBe(0);
    expect(await alertCount(t.userIds.owner, "comment_created", issue4.id)).toBe(2);
  });
});

